module transport;
import contracts;

fn dispatch(request: contracts.CancelRequest, stored: contracts.StoreOutcome) -> contracts.CancelOutcome {
  if text.is_empty(request.value) {
    contracts.CancelOutcome::Malformed
  } else {
    if text.contains_control(request.value) {
      contracts.CancelOutcome::Malformed
    } else {
      contracts.stored_decision(stored)
    }
  }
}

